@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",RWORD)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@TEXT(P_N@R_i@)@")@
