@UPJ(JSON_test_config.Verb[@R_i@].Student_answer, "@TEXT(P_V@R_i@)@")@
@UPJ(JSON_test_config.Verb[@R_i@].correctness, @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",RWORD)@)@

